-- =====================================================================================
-- ROLES ONLY · the access design  (core room, zone "control")
-- WHERE: ERP TEST. The top bar must say ERP TEST.
-- HOW:   SQL Editor → New query → paste this WHOLE file → Run. Safe to run again.
-- CHECK: the last result is a list of checks. Every row must say PASS.
-- START OVER (test only):  drop schema core cascade;
--
-- Boxes → roles → people:
--   core.access_items .... every box that can be granted (93): 24 Sellora screens, 50 ERP screens, 19 extra rights
--   core.roles ........... your role chart (33 roles), department → team → role
--   core.role_access ..... the boxes inside each role (filled below from the role chart)
--   core.people .......... gets role_id (one role each) and brands — people themselves are loaded later
--   core.person_access ... a person's extras (+) / removals (−) — only for people who don't fit a role exactly
--   core.access_now ...... (view) what each person can do now: role + extras − removals; admin = everything
--   core.can(box, brand) . the one question screens will ask: "may I?"
-- Dropped on purpose: old screens (Old Production App, Follow-ups, India Stock, In Production) and unused bd* flags.
-- (generated by migration/tools/roles-today.js from the role chart — edit the template, not this file)
-- =====================================================================================

create schema if not exists core;
revoke all on schema core from anon, authenticated;
grant usage on schema core to service_role;

-- brands (on the Shopify project this exists already; on a new test project it is made here as Shopify makes it)
create table if not exists public.stores (
  id text primary key check (id ~ '^[A-Z]{2,5}$'), name text not null, shopify_domain text not null unique,
  currency text not null default 'USD', timezone text not null default 'America/Los_Angeles', active boolean not null default true
);
alter table public.stores enable row level security;
insert into public.stores (id, name, shopify_domain) values
  ('RBP', 'Ridhi Block Print', 'ridhiblockprint.myshopify.com'), ('CPC', 'Cotton Print Club', 'liquidationfashion.myshopify.com')
on conflict (id) do nothing;

-- ----------------------------------------------------------------- 1. the boxes
create table if not exists core.access_items (
  key         text primary key check (key ~ '^(sellora|erp|right):[a-zA-Z0-9]+$'),
  app         text not null check (app in ('sellora','erp','right')),
  code        text not null,
  name        text not null,
  menu_group  text not null,
  sort        int  not null default 0,
  active      boolean not null default true,
  check (key = app || ':' || code)
);

-- ----------------------------------------------------------------- 2. the roles
create table if not exists core.roles (
  id           bigint generated always as identity primary key,
  code         text not null unique check (code ~ '^[a-z][a-z0-9_]*$'),
  name         text not null,
  department   text not null,
  team         text not null,
  is_admin     boolean not null default false,
  brand        text references public.stores (id),
  limit_note   text,
  cannot_note  text,
  sort         int not null default 0,
  active       boolean not null default true
);

-- ----------------------------------------------------------------- 3. the boxes in each role
create table if not exists core.role_access (
  role_id   bigint not null references core.roles (id) on delete cascade,
  item_key  text   not null references core.access_items (key),
  primary key (role_id, item_key)
);
create index if not exists role_access_item on core.role_access (item_key);

-- ----------------------------------------------------------------- 4. people (same table as the full core room; filled later)
create table if not exists core.people (
  id          bigint generated always as identity primary key,
  email       text not null unique check (email = lower(trim(email)) and email like '%_@_%'),
  name        text not null check (length(trim(name)) > 0),
  kind        text not null default 'staff' check (kind in ('staff','vendor','legacy')),
  vendor_id   bigint,
  role_id     bigint references core.roles (id),
  phone       text,
  brands      text[] not null default '{RBP,CPC}' check (brands <@ array['RBP','CPC']::text[]),
  active      boolean not null default true
);

-- ----------------------------------------------------------------- 5. one person's difference from their role
create table if not exists core.person_access (
  person_id  bigint not null references core.people (id) on delete cascade,
  item_key   text   not null references core.access_items (key),
  effect     text   not null check (effect in ('add','remove')),
  note       text,
  primary key (person_id, item_key)
);

alter table core.access_items  enable row level security;
alter table core.roles         enable row level security;
alter table core.role_access   enable row level security;
alter table core.people        enable row level security;
alter table core.person_access enable row level security;

-- ----------------------------------------------------------------- 6. what each person can do (worked out)
create or replace view core.access_now as
with p as (
  select pe.id as person_id, pe.email, pe.name, r.code as role_code, coalesce(r.is_admin, false) as is_admin,
         case when r.brand is not null then array[r.brand] else pe.brands end as brands, pe.role_id
    from core.people pe left join core.roles r on r.id = pe.role_id
   where pe.active
)
select p.person_id, p.email, p.name, p.role_code, p.brands, i.key as item_key, i.app, i.code, i.name as item_name,
       case when p.is_admin then 'admin' when ra.item_key is not null then 'role' else 'extra' end as via
  from p
  join core.access_items i on i.active
  left join core.role_access   ra on ra.role_id = p.role_id and ra.item_key = i.key
  left join core.person_access pa on pa.person_id = p.person_id and pa.item_key = i.key
 where p.is_admin
    or ((ra.item_key is not null or pa.effect = 'add') and pa.effect is distinct from 'remove');

create or replace function core.me_email() returns text
language sql stable as $$
  select case when auth.jwt()->>'iss' = 'https://securetoken.google.com/price-research-48ff3' and auth.jwt()->>'aud' = 'price-research-48ff3'
              then nullif(lower(trim(auth.jwt()->>'email')), '') end
$$;
create or replace function core.me_id() returns bigint
language sql stable security definer set search_path = core, public as $$
  select id from core.people where email = core.me_email() and active limit 1
$$;
create or replace function core.can(p_item text, p_brand text default null) returns boolean
language sql stable security definer set search_path = core, public as $$
  select exists (select 1 from core.access_now a where a.person_id = core.me_id() and a.item_key = p_item
                    and (p_brand is null or p_brand = any (a.brands)))
$$;
revoke all on function core.me_id(), core.can(text, text) from public;
grant execute on function core.me_email(), core.me_id(), core.can(text, text) to authenticated, service_role;

