-- ----------------------------------------------------------------- 9. live tests (everything they write is undone)
create temp table if not exists _t (n int, check_name text, result text);
truncate _t;
do $$
declare a bigint; t1 bigint; got int; r text;
begin
  r := 'FAIL';
  begin
    insert into core.roles (code, name, department, team) values ('test_qc', 'Test QC', 'Production', 'Shop floor') returning id into t1;
    insert into core.role_access (role_id, item_key) values (t1, 'erp:qc'), (t1, 'erp:qcalt'), (t1, 'right:prodEdit');
    insert into core.people (email, name, role_id) values ('test.r@ridhi.test', 'Test R', t1) returning id into a;
    insert into core.person_access (person_id, item_key, effect) values (a, 'erp:fgi', 'add'), (a, 'erp:qcalt', 'remove');
    select count(*) into got from core.access_now where person_id = a and item_key in ('erp:qc', 'right:prodEdit', 'erp:fgi');
    if got = 3 and not exists (select 1 from core.access_now where person_id = a and item_key = 'erp:qcalt') then r := 'PASS'; else r := 'FAIL: got ' || got || ' of 3'; end if;
    raise exception 'undo';
  exception when others then if sqlerrm <> 'undo' then r := 'FAIL: ' || sqlerrm; end if;
  end;
  insert into _t values (20, 'role boxes + extras − removals give the right access', r);

  r := 'FAIL: it was accepted';
  begin
    insert into core.roles (code, name, department, team) values ('test_x', 'Test X', 'Other', 'Test') returning id into t1;
    insert into core.role_access (role_id, item_key) values (t1, 'right:bdFill');
    raise exception 'undo';
  exception when foreign_key_violation then r := 'PASS';
            when others then if sqlerrm <> 'undo' then r := 'FAIL: ' || sqlerrm; end if;
  end;
  insert into _t values (21, 'a box that is not on the list is refused (no more "bdFill")', r);

  r := 'FAIL';
  begin
    insert into core.people (email, name, role_id) values ('test.adm@ridhi.test', 'Test Admin', (select id from core.roles where code = 'owneradmin')) returning id into a;
    select count(*) into got from core.access_now where person_id = a;
    r := case when got = (select count(*) from core.access_items where active) then 'PASS' else 'FAIL: ' || got || ' boxes' end;
    raise exception 'undo';
  exception when others then if sqlerrm <> 'undo' then r := 'FAIL: ' || sqlerrm; end if;
  end;
  insert into _t values (22, 'the Owner / Director role gets every box', r);

  r := 'FAIL';
  begin
    insert into core.people (email, name, role_id, brands) values ('test.ads@ridhi.test', 'Test Ads', (select id from core.roles where code = 'adslist'), '{RBP,CPC}') returning id into a;
    select count(*) into got from core.access_now where person_id = a and brands = array['RBP'];
    r := case when got > 0 and not exists (select 1 from core.access_now where person_id = a and 'CPC' = any (brands)) then 'PASS' else 'FAIL' end;
    raise exception 'undo';
  exception when others then if sqlerrm <> 'undo' then r := 'FAIL: ' || sqlerrm; end if;
  end;
  insert into _t values (23, 'a one-brand role (Ads & listing, Ridhi only) sees only RBP', r);
end $$;

-- ----------------------------------------------------------------- 10. checks: every row must say PASS
select n, check_name, result from (
  select 1 as n, '5 role tables + the access view exist' as check_name,
         case when (select count(*) from pg_tables where schemaname = 'core' and tablename in ('access_items','roles','role_access','people','person_access')) = 5
               and to_regclass('core.access_now') is not null then 'PASS' else 'FAIL' end as result
  union all select 2, 'boxes: 24 Sellora screens · 50 ERP screens · 19 rights',
         case when (select count(*) from core.access_items where app = 'sellora') = 24 and (select count(*) from core.access_items where app = 'erp') = 50
               and (select count(*) from core.access_items where app = 'right') = 19 then 'PASS'
              else 'FAIL: ' || (select string_agg(app || ' ' || n, ', ') from (select app, count(*) n from core.access_items group by app) x) end
  union all select 3, 'old screens and bd* flags are not boxes',
         case when not exists (select 1 from core.access_items where code in ('ptapp','follow','india','prod') or code like 'bd%') then 'PASS' else 'FAIL' end
  union all select 4, '33 roles in 4 departments',
         case when (select count(*) from core.roles) = 33 and (select count(distinct department) from core.roles) = 4 then 'PASS'
              else 'FAIL: ' || (select count(*) from core.roles) || ' roles' end
  union all select 5, '341 boxes placed in roles',
         case when (select count(*) from core.role_access) = 341 then 'PASS' else 'FAIL: ' || (select count(*) from core.role_access) end
  union all select 6, 'exactly one admin role (Owner / Director)',
         case when (select count(*) from core.roles where is_admin) = 1 and exists (select 1 from core.roles where code = 'owneradmin' and is_admin) then 'PASS' else 'FAIL' end
  union all select 7, 'browsers cannot read any of it',
         case when not has_schema_privilege('anon', 'core', 'usage') and not has_schema_privilege('authenticated', 'core', 'usage') then 'PASS' else 'FAIL' end
  union all select 8, 'no test rows left behind',
         case when not exists (select 1 from core.people where email like '%@ridhi.test') and not exists (select 1 from core.roles where code like 'test_%') then 'PASS' else 'FAIL' end
  union all select n, check_name, result from _t
) x order by n;

